```
cases := []struct {
    name string
    mode dnsTestMode
    args dnsTestArgs
}{{
    name: "agnhost",
    mode: AgnHost,
}, {
    name: "jessie",
    mode: Image
    image: imageutils.GetE2EImage(imageutils.JessieDnsutils)
}}
for _, case := range cases {
    cmd, ctr, files := makeDNSTester(case.name, case.mode, namesToResolve, nil, "", f.Namespace.Name, framework.TestContext.ClusterDNSDomain, framework.TestContext.ClusterIsIPv6())
